index 5890db241..57fec73dd 100644
--- a/packages/workflow/src/utils.ts
+++ b/packages/workflow/src/utils.ts
@@ -87,6 +87,14 @@ function syntaxNodeToValue(expression?: SyntaxNode | null): unknown {
 			return expression.value;
 		case Syntax.ArrayExpression:
 			return expression.elements.map((exp) => syntaxNodeToValue(exp));
+		case Syntax.UnaryExpression: {
+			// Support signed numbers, e.g. `{ a: -1 }` or `{ a: +1 }`
+			const argument = syntaxNodeToValue(expression.argument);
+			if (typeof argument !== 'number') return undefined;
+			if (expression.operator === '-') return -argument;
+			if (expression.operator === '+') return argument;
+			return undefined;
+		}
 		default:
 			return undefined;
 	}
